/**
 * Byte signifying the scope of an Intent
 *
 * This enum specifies the intent scope. Two intents for different scopes
 * should never collide, so no signature provided for one intent scope can be
 * used for another, even when the serialized data itself may be the same.
 *
 * # BCS
 *
 * The BCS serialized form for this type is defined by the following ABNF:
 *
 * ```text
 * intent-scope = u8
 * ```
 */
export type IntentScope =
    /**
     * Used for a user signature on a transaction data.
     */
    | "transactionData"
    /**
     * Used for an authority signature on transaction effects.
     */
    | "transactionEffects"
    /**
     * Used for an authority signature on a checkpoint summary.
     */
    | "checkpointSummary"
    /**
     * Used for a user signature on a personal message.
     */
    | "personalMessage"
    /**
     * Used for an authority signature on a user signed transaction.
     */
    | "senderSignedTransaction"
    /**
     * Used as a signature representing an authority's proof of possession of
     * its authority key.
     */
    | "proofOfPossession"
    /**
     * Deprecated. Should not be reused. Introduced for bridge purposes but was
     * never included in messages.
     */
    | "bridgeEventDeprecated"
    /**
     * Used for consensus authority signature on block's digest.
     */
    | "consensusBlock"
    /**
     * Used for reporting peer addresses in discovery
     */
    | "discoveryPeers"
    /**
     * Used for authority capabilities from non-committee authorities.
     */
    | "authorityCapabilities"

export const FfiConverterTypeIntentScope = (() => {
    const ordinalConverter = FfiConverterInt32;
    class FFIConverter extends AbstractFfiConverterByteArray<IntentScope> {
        read(from: RustBuffer): IntentScope {
            switch (ordinalConverter.read(from)) {
                case 1: return "transactionData";
                case 2: return "transactionEffects";
                case 3: return "checkpointSummary";
                case 4: return "personalMessage";
                case 5: return "senderSignedTransaction";
                case 6: return "proofOfPossession";
                case 7: return "bridgeEventDeprecated";
                case 8: return "consensusBlock";
                case 9: return "discoveryPeers";
                case 10: return "authorityCapabilities";
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: IntentScope, into: RustBuffer): void {
            switch (value) {
                case "transactionData": ordinalConverter.write(1, into); break;
                case "transactionEffects": ordinalConverter.write(2, into); break;
                case "checkpointSummary": ordinalConverter.write(3, into); break;
                case "personalMessage": ordinalConverter.write(4, into); break;
                case "senderSignedTransaction": ordinalConverter.write(5, into); break;
                case "proofOfPossession": ordinalConverter.write(6, into); break;
                case "bridgeEventDeprecated": ordinalConverter.write(7, into); break;
                case "consensusBlock": ordinalConverter.write(8, into); break;
                case "discoveryPeers": ordinalConverter.write(9, into); break;
                case "authorityCapabilities": ordinalConverter.write(10, into); break;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        allocationSize(value: IntentScope): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

