const uniffiTypeTransactionObjectFactory: UniffiObjectFactory<Transaction> =
  (() => {
    /// <reference lib="es2021" />
    const registry =
      typeof (globalThis as any).FinalizationRegistry !== 'undefined'
        ? new (globalThis as any).FinalizationRegistry(
            (heldValue: UnsafeMutableRawPointer) => {
             uniffiTypeTransactionObjectFactory.freePointer(heldValue);
            }
          )
        : null;

    return {
      create(pointer: UnsafeMutableRawPointer): Transaction {
        const instance = Object.create(Transaction.prototype);
        instance[pointerLiteralSymbol] = pointer;
        instance[destructorGuardSymbol] = this.bless(pointer);
        instance[uniffiTypeNameSymbol] = 'Transaction';
        return instance;
      },

      bless(p: UnsafeMutableRawPointer): UniffiRustArcPtr {
        const ptr = {
          p, // make sure this object doesn't get optimized away.
          markDestroyed: () => undefined,
        };
        if (registry) {
          registry.register(ptr, p, ptr);
        }
        return ptr;
      },

      unbless(ptr: UniffiRustArcPtr) {
        if (registry) {
          registry.unregister(ptr);
        }
      },

      pointer(obj: Transaction): UnsafeMutableRawPointer {
        if (typeof (obj as any)[destructorGuardSymbol] === 'undefined') {
          throw new UniffiInternalError.UnexpectedNullPointer();
        }
        return (obj as any)[pointerLiteralSymbol];
      },

      clonePointer(obj: Transaction): UnsafeMutableRawPointer {
        const handleArg = this.pointer(obj);
        return uniffiCaller.rustCall(
          /*caller:*/ (callStatus) => {
            return FFI_DYNAMIC_LIB.uniffi_iota_sdk_ffi_fn_clone_transaction([
              handleArg, callStatus
            ]);
          },
          /*liftString:*/ FfiConverterString.lift
        );
      },

      freePointer(handleArg: UnsafeMutableRawPointer): void {
        uniffiCaller.rustCall(
          /*caller:*/ (callStatus) => {
            return FFI_DYNAMIC_LIB.uniffi_iota_sdk_ffi_fn_free_transaction([
              handleArg, callStatus
            ]);
          },
          /*liftString:*/ FfiConverterString.lift
        );
      },

      isConcreteType(obj: any): obj is Transaction {
        return (
          obj[destructorGuardSymbol] && obj[uniffiTypeNameSymbol] === 'Transaction'
        );
      },
    };
  })();

